t_index":3},{"id":"fb353e8c-a494-4dc7-8f1c-2b15b6f08efe","prompt":"أي عبارة تلخص هدف درس «الشروط واتخاذ القرار في JavaScript»؟","options":["افهم المستودعات البعيدة ورفع المشروع ومراجعة التغييرات.","استخدم if وelse وswitch لاختيار ما ينفذه البرنامج.","نفّذ مجموعة أوامر أكثر من مرة دون تكرار كتابة الكود.","استخدم for وwhile لتكرار الأوامر والتحكم في عدد مرات التنفيذ."],"quiz_id":"8ee98caf-2da0-41ad-a2a3-797866e20835","sort_order":1,"explanation":"استخدم if وelse وswitch لاختيار ما ينفذه البرنامج.","correct_index":1}]$programming_snapshot$::jsonb)
on conflict ("id") do update set "quiz_id" = excluded."quiz_id", "prompt" = excluded."prompt", "options" = excluded."options", "correct_index" = excluded."correct_index", "explanation" = excluded."explanation", "sort_order" = excluded."sort_order";

